const { evaluate } = require('./s5_expr.js');
const { Cache } = require('./s7_cache.js');

try {
    const result1 = evaluate('-(2+3)*2');
    console.log('-(2+3)*2 =', result1);

    const result2 = evaluate('2*-3');
    console.log('2*-3 =', result2);

    if (result1 === -10 && result2 === -6) {
        console.log('✅ All specific test cases pass!');
    } else {
        console.log('❌ Some test cases failed');
        process.exit(1);
    }

    // Test Cache delete and clear methods
    console.log('\nTesting Cache delete and clear methods...');

    const cache = new Cache(3);

    // Test delete on non-existent key
    if (cache.delete('nonexistent') === false) {
        console.log('✅ delete returns false for non-existent key');
    } else {
        console.log('❌ delete should return false for non-existent key');
        process.exit(1);
    }

    // Test delete on existing key
    cache.set('a', 1);
    cache.set('b', 2);
    if (cache.delete('a') === true) {
        console.log('✅ delete returns true for existing key');
    } else {
        console.log('❌ delete should return true for existing key');
        process.exit(1);
    }

    // Test that deleted key is actually removed
    if (cache.get('a') === undefined) {
        console.log('✅ deleted key is actually removed');
    } else {
        console.log('❌ deleted key still exists');
        process.exit(1);
    }

    // Test clear method
    cache.set('c', 3);
    cache.set('d', 4);
    cache.clear();

    if (cache.size() === 0) {
        console.log('✅ clear removes all entries');
    } else {
        console.log('❌ clear did not remove all entries');
        process.exit(1);
    }

    console.log('✅ All Cache tests pass!');

} catch (error) {
    console.error('Error:', error.message);
    process.exit(1);
}

