    cache.set('b', 2);
    if (cache.delete('a') === true) {
        console.log('✅ delete returns true for existing key');
    } else {
        console.log('❌ delete should return true for existing key');
        process.exit(1);
    }

    // Test that deleted key is actually removed
    if (cache.get('a') === undefined) {
        console.log('✅ deleted key is actually removed');
    } else {
        console.log('❌ deleted key still exists');
        process.exit(1);
    }

    // Test clear method
    cache.set('c', 3);
    cache.set('d', 4);
    cache.clear();

    if (cache.size() === 0) {
        console.log('✅ clear removes all entries');
    } else {
        console.log('❌ clear did not remove all entries');
        process.exit(1);
    }

    console.log('✅ All Cache tests pass!');

} catch (error) {
    console.error('Error:', error.message);
    process.exit(1);
}

